const photoFiles={'2800':'Kochi Castle 2025.jpg','2801':'Hirome Market 01.jpg','2802':'Katsurahama.jpg','2803':'Kochi Prefectural Makino Botanical Garden01s3872.jpg','2804':'Chikurinji Kochi03n3872.jpg','2805':'龍河洞 - panoramio.jpg','2806':'Nikobuti04.jpg','2807':'飛龍の滝 - panoramio.jpg','2808':'中津渓谷（雨竜の滝）.jpg','2809':'Muroto Cape.JPG','2810':'Monet-Marumottan-mizu02.jpg','2811':'Shimanto sada chinkabashi.jpg','2812':'Shimanto River And Iwama Bridge 1.jpg','2813':'Cape Ashizuri.jpg','2814':'Tatsukushi 01.JPG','2815':'Ashizuri Aquarium SATOUMI.jpg','2816':'Kashiwajima Island, Otsuki, Kochi Prefecture, as viewed from a nearby observation deck. August 2013.jpg','2817':'Gate, Kochi Castle - Apr 13, 2023 (2).jpg','2818':'Mikurodo cave, Muroto city 02.jpg'};const photos={};for(const p of places){const f=photoFiles[p.id];photos[p.id]={src:cf(f),alt:p.name,source:cp(f)};}photos['2807']={src:'images/licensed/yasui-gorge-nakashi-54360037444.webp',alt:places.find(p=>p.id===2807)?.name||'야스이계곡',source:'https://www.flickr.com/photos/81497476@N00/54360037444/',author:'nakashi',license:'CC BY-SA 2.0',licenseUrl:'https://creativecommons.org/licenses/by-sa/2.0/'};
const foods=[
{name:T('가쓰오노 타타키','かつおのたたき'),area:T('고치 전역','高知県全域'),kind:T('가다랑어·향토','かつお・郷土'),where:T('고치시·해안 전역','高知市・沿岸全域'),description:T('가다랑어 겉면을 강한 불에 짧게 구워 향을 입히고 소금이나 폰즈, 마늘·양파·묘가 등을 곁들여 먹는 고치 대표 음식입니다.','かつおの表面を強火で短く炙り、塩またはポン酢、にんにく、玉ねぎ、みょうがなどと味わう高知を代表する料理です。'),source:'https://visitkochijapan.com/en/'},
{name:T('사와치요리','皿鉢料理'),area:A.city,kind:T('향토·모둠요리','郷土・盛り合わせ'),where:T('고치 전역','高知県全域'),description:T('큰 접시에 사시미·초밥·구이·조림 등을 화려하게 담아 여러 사람이 함께 나눠 먹는 도사 지역의 잔치 음식입니다.','大皿に刺身、寿司、焼き物、煮物などを豪快に盛り、複数人で取り分ける土佐の宴席料理です。'),source:'https://visitkochijapan.com/en/'},
{name:T('나베야키 라멘','鍋焼きラーメン'),area:T('스사키','須崎'),kind:T('라멘·지역음식','ラーメン・ご当地'),where:T('스사키시','須崎市'),description:T('작은 뚝배기에 닭육수·간장 국물과 가는 면, 달걀·대파·어묵을 넣어 끓여내는 스사키의 대표 지역 라멘입니다.','小さな土鍋に鶏ガラ醤油スープ、細麺、卵、ねぎ、ちくわなどを入れて煮込む須崎のご当地ラーメンです。'),source:'https://visitkochijapan.com/en/'},
{name:T('이모켄피','芋けんぴ'),area:T('고치 전역','高知県全域'),kind:T('고구마과자·기념품','さつまいも菓子・土産'),where:T('고치 전역','高知県全域'),description:T('가늘게 썬 고구마를 바삭하게 튀겨 설탕 시럽을 입힌 고치의 대표 간식으로 시장과 전문점에서 갓 튀긴 제품도 쉽게 볼 수 있습니다.','細切りのさつまいもをカリッと揚げ、砂糖蜜を絡めた高知を代表する菓子で、市場や専門店では揚げたての商品も見つかります。'),source:'https://visitkochijapan.com/en/'},
{name:T('도사 아카우시','土佐あかうし'),area:A.niyodo,kind:T('와규·브랜드소','和牛・ブランド牛'),where:T('고치 중산간·고치시','高知中山間・高知市'),description:T('고치의 갈색 화우 품종으로 적당한 마블링과 붉은살의 진한 감칠맛이 특징이며 스테이크·구이·덮밥 등으로 즐깁니다.','高知の褐毛和種で、ほどよい霜降りと赤身の濃いうま味が特徴。ステーキ、焼肉、丼などで味わいます。'),source:'https://visitkochijapan.com/en/'},
{name:T('시만토 장어','四万十うなぎ'),area:A.shimanto,kind:T('장어·강음식','うなぎ・川料理'),where:T('시만토강 유역','四万十川流域'),description:T('시만토강 유역에서 즐기는 장어 요리로 구이와 덮밥 형태가 대표적이며, 강새우·아오사 등 다른 시만토 식재료와 함께 소개됩니다.','四万十川流域で味わううなぎ料理で、蒲焼きや丼が代表的。川えび、青さのりなど他の四万十食材と一緒に楽しまれます。'),source:'https://visitkochijapan.com/en/highlights/shimantoriver'},
{name:T('도사 지로','土佐ジロー'),area:A.muroto,kind:T('토종닭·달걀','地鶏・卵'),where:T('고치 동부·현내','高知東部・県内'),description:T('고치의 토종닭 브랜드로 작고 탄력 있는 육질과 진한 맛의 달걀이 특징이며 숯불구이·달걀요리로 많이 먹습니다.','高知の地鶏ブランドで、小ぶりで弾力ある肉質と濃厚な卵が特徴。炭火焼きや卵料理でよく味わわれます。'),source:'https://visitkochijapan.com/en/'}];
